/* Su Finca — Portal del agricultor
   Conecta con el MISMO proyecto Firebase de la app Android
   (colección "lotes" compartida en tiempo real).
   SDK web de Firebase v10+ (modular). */

import { initializeApp } from "https://www.gstatic.com/firebasejs/10.14.1/firebase-app.js";
import {
  getAuth,
  onAuthStateChanged,
  signInAnonymously,
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  signOut,
  sendEmailVerification,
  sendPasswordResetEmail,
  linkWithCredential,
  EmailAuthProvider,
  getIdToken
} from "https://www.gstatic.com/firebasejs/10.14.1/firebase-auth.js";
import {
  getFirestore,
  collection,
  query,
  where,
  orderBy,
  limit,
  onSnapshot,
  addDoc,
  doc,
  setDoc,
  getDoc,
  updateDoc,
  deleteDoc,
  deleteField,
  getDocs
} from "https://www.gstatic.com/firebasejs/10.14.1/firebase-firestore.js";
import { firebaseConfig } from "./firebase-config.js";

/* ---------- Utilidades ---------- */
const $ = (id) => document.getElementById(id);

// Escapa texto de usuario antes de inyectarlo al HTML (anti-XSS).
function esc(s) {
  return String(s ?? "").replace(/[&<>"']/g, (c) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
  }[c]));
}

// Correo válido en palabras sencillas: algo@algo.algo
function correoValido(c) {
  const partes = String(c || "").trim().split("@");
  return partes.length === 2 && partes[0].length > 0 &&
    partes[1].split(".").length >= 2 &&
    partes[1].split(".").every((p) => p.length > 0);
}

/* ---------- Arranque ---------- */
if (String(firebaseConfig.apiKey || "").startsWith("TU_")) {
  $("avisoConfig").style.display = "block";
} else {
  const app = initializeApp(firebaseConfig);
  const auth = getAuth(app);
  const db = getFirestore(app);
  iniciarPortal(auth, db);
}

function iniciarPortal(auth, db) {
  let uid = null;
  let cancelarLotes = null;
  let cancelarSensores = [];
  let lotesCache = [];

  /* ----- Estado de sesión ----- */
  onAuthStateChanged(auth, async (user) => {
    if (cancelarLotes) { cancelarLotes(); cancelarLotes = null; }
    if (cancelarSensores) { cancelarSensores.forEach((c) => c()); cancelarSensores = []; }
    if (user) {
      uid = user.uid;
      $("panelAcceso").style.display = "none";
      $("panelLotes").style.display = "block";
      $("panelSensores").style.display = "block";
      $("panelProductos").style.display = "block";
      $("panelCalculadora").style.display = "block";
      $("navSecciones").style.display = "inline-flex";
      $("enlaceSalir").style.display = "inline";
      // Aviso para quien entró sin cuenta: puede guardar sus lotes.
      $("avisoAnonimo").style.display = user.isAnonymous ? "block" : "none";
      pintarBarraCuenta(user);
      try { await asegurarPerfil(db, user); } catch (e) {
        console.warn("No se pudo guardar el perfil:", e);
      }
      suscribirLotes();
      pintarCatalogo("");
    } else {
      uid = null;
      $("panelAcceso").style.display = "block";
      $("panelLotes").style.display = "none";
      $("panelSensores").style.display = "none";
      $("panelProductos").style.display = "none";
      $("panelCalculadora").style.display = "none";
      $("navSecciones").style.display = "none";
      $("enlaceSalir").style.display = "none";
      $("errorAcceso").textContent = "";
      $("okAcceso").textContent = "";
    }
  });

  /* ----- "Mi cuenta" en el portal ----- */
  function pintarBarraCuenta(user) {
    const barra = $("barraCuenta");
    if (user.isAnonymous) {
      barra.style.display = "none";
      return;
    }
    barra.style.display = "block";
    const verificado = user.emailVerified;
    barra.innerHTML =
      `<strong>Mi cuenta:</strong> ${esc(user.email || "")} · ` +
      (verificado
        ? `<span style="color:var(--verde-oscuro)">✓ Correo confirmado</span>`
        : `<span style="color:var(--rojo)">⚠ Correo sin confirmar</span> ` +
          `<button class="btn btn-claro btn-pequeno" id="btnReenviar" style="border:1px solid #cfd8d2">Reenviar correo</button>`);
    const b = $("btnReenviar");
    if (b) b.onclick = async () => {
      try {
        await sendEmailVerification(auth.currentUser);
        barra.innerHTML = `<strong>Mi cuenta:</strong> ${esc(user.email || "")} · Te enviamos el correo de confirmación. Revísalo cuando puedas.`;
      } catch (e) {
        barra.innerHTML = `<strong>Mi cuenta:</strong> ${esc(user.email || "")} · No se pudo enviar el correo: ${esc(mensajeError(e))}`;
      }
    };
  }

  /* ----- Perfil usuarios/{uid}: igual que la app Android ----- */
  async function asegurarPerfil(db, user) {
    const ref = doc(db, "usuarios", user.uid);
    const ahora = Date.now();
    const foto = await getDoc(ref);
    if (!foto.exists()) {
      await setDoc(ref, {
        email: user.email || "",
        nombre: "",
        telefono: "",
        nombreFinca: "",
        municipio: "",
        plan: "gratis",
        planDesde: ahora,
        creadoEn: ahora,
        ultimaSesion: ahora,
        clientePagoId: ""
      });
    } else {
      await setDoc(ref, { ultimaSesion: ahora }, { merge: true });
    }
  }

  /* ----- Crear cuenta (o vincular la sesión sin cuenta) ----- */
  async function crearCuentaConCorreo(correo, clave) {
    const eraAnonimo = auth.currentUser && auth.currentUser.isAnonymous;
    let cred;
    try {
      if (eraAnonimo) {
        // Vincula: conserva el MISMO uid y los lotes del modo sin cuenta.
        cred = await linkWithCredential(
          auth.currentUser, EmailAuthProvider.credential(correo, clave));
      } else {
        cred = await createUserWithEmailAndPassword(auth, correo, clave);
      }
    } catch (e) {
      if (e.code === "auth/email-already-in-use" && eraAnonimo) {
        throw new Error("Ese correo ya tiene una cuenta. Tus lotes están en " +
          "esta sesión sin cuenta; si sales y entras con la otra cuenta no " +
          "los verás. Escríbenos a ecoandesdrone@gmail.com y te ayudamos a unirlos.");
      }
      throw e;
    }
    const nuevo = cred.user;
    try { await sendEmailVerification(nuevo); } catch (e) {
      console.warn("No se pudo enviar la verificación:", e);
    }
    try { await asegurarPerfil(db, nuevo); } catch (e) {
      console.warn("No se pudo guardar el perfil:", e);
    }
    return eraAnonimo
      ? "¡Listo! Tus lotes quedaron guardados en tu cuenta. Te enviamos un correo de confirmación."
      : "¡Cuenta creada! Te enviamos un correo de confirmación. Ábrelo cuando puedas.";
  }

  function mostrarErrorAcceso(prefijo, e) {
    $("okAcceso").textContent = "";
    $("errorAcceso").textContent = prefijo + mensajeError(e);
  }

  /* ----- Acceso ----- */
  $("btnEntrar").onclick = async () => {
    $("errorAcceso").textContent = "";
    $("okAcceso").textContent = "";
    const correo = $("correo").value.trim();
    const clave = $("clave").value;
    if (!correoValido(correo)) {
      $("errorAcceso").textContent = "Revisa el correo: le falta algo (el @ o el dominio).";
      return;
    }
    if (!clave) { $("errorAcceso").textContent = "Escribe tu clave."; return; }
    try {
      const cred = await signInWithEmailAndPassword(auth, correo, clave);
      try { await asegurarPerfil(db, cred.user); } catch (e) {
        console.warn("No se pudo guardar el perfil:", e);
      }
    } catch (e) { mostrarErrorAcceso("No se pudo entrar: ", e); }
  };
  $("btnCrearCuenta").onclick = () => {
    // Abre el formulario de registro (no usa los campos de "Ya tengo cuenta")
    $("errorAcceso").textContent = "";
    $("okAcceso").textContent = "";
    $("errorRegistro").textContent = "";
    $("formRegistro").style.display = "block";
    $("btnCrearCuenta").style.display = "none";
    $("correoNuevo").focus();
  };
  $("btnVolverAcceso").onclick = () => {
    $("formRegistro").style.display = "none";
    $("btnCrearCuenta").style.display = "";
    $("errorRegistro").textContent = "";
  };
  $("btnRegistrar").onclick = async () => {
    $("errorRegistro").textContent = "";
    $("okAcceso").textContent = "";
    const correo = $("correoNuevo").value.trim();
    const clave = $("claveNueva").value;
    if (!correoValido(correo)) {
      $("errorRegistro").textContent = "Revisa el correo: debe verse como nombre@correo.com.";
      return;
    }
    if (clave.length < 6) {
      $("errorRegistro").textContent = "La clave debe tener al menos 6 letras o números.";
      return;
    }
    try {
      const msg = await crearCuentaConCorreo(correo, clave);
      $("formRegistro").style.display = "none";
      $("btnCrearCuenta").style.display = "";
      $("okAcceso").textContent = msg;
    } catch (e) {
      $("errorRegistro").textContent = "No se pudo crear la cuenta: " + mensajeError(e);
    }
  };
  // Guardar los lotes del modo sin cuenta en una cuenta con correo.
  $("btnVincular").onclick = async () => {
    $("errorVinculo").textContent = "";
    const correo = $("correoVinculo").value.trim();
    const clave = $("claveVinculo").value;
    if (!correoValido(correo)) {
      $("errorVinculo").textContent = "Revisa el correo: debe verse como nombre@correo.com.";
      return;
    }
    if (clave.length < 6) {
      $("errorVinculo").textContent = "La clave debe tener al menos 6 letras o números.";
      return;
    }
    try {
      await crearCuentaConCorreo(correo, clave);
      $("avisoAnonimo").style.display = "none";
    } catch (e) {
      $("errorVinculo").textContent = "No se pudo guardar: " + mensajeError(e);
    }
  };
  $("btnSinCuenta").onclick = async () => {
    $("errorAcceso").textContent = "";
    $("okAcceso").textContent = "";
    try { await signInAnonymously(auth); }
    catch (e) { mostrarErrorAcceso("No se pudo entrar sin cuenta: ", e); }
  };
  $("enlaceOlvido").onclick = async (e) => {
    e.preventDefault();
    $("errorAcceso").textContent = "";
    $("okAcceso").textContent = "";
    const correo = $("correo").value.trim();
    if (!correoValido(correo)) {
      $("errorAcceso").textContent = "Escribe tu correo arriba para enviarte el enlace.";
      return;
    }
    try {
      await sendPasswordResetEmail(auth, correo);
      $("okAcceso").textContent = "Te enviamos un correo para crear una clave nueva. Revisa también el spam.";
    } catch (err) { mostrarErrorAcceso("No se pudo enviar el correo: ", err); }
  };
  $("enlaceSalir").onclick = async (e) => { e.preventDefault(); await signOut(auth); };

  /* ----- Mostrar / ocultar clave ----- */
  function alternarOjo(botonId, campoId) {
    const b = $(botonId), c = $(campoId);
    if (b && c) b.onclick = () => {
      const ver = c.type === "password";
      c.type = ver ? "text" : "password";
      b.textContent = ver ? "🙈" : "👁️";
    };
  }
  alternarOjo("ojoClave", "clave");
  alternarOjo("ojoClaveVinculo", "claveVinculo");
  alternarOjo("ojoClaveNueva", "claveNueva");

  function mensajeError(e) {
    if (e instanceof Error && !e.code) return e.message;
    const codigos = {
      "auth/invalid-credential": "correo o clave incorrectos.",
      "auth/user-not-found": "ese correo no tiene cuenta. Créala primero.",
      "auth/wrong-password": "clave incorrecta.",
      "auth/weak-password": "la clave debe tener al menos 6 letras o números.",
      "auth/email-already-in-use": "ese correo ya tiene cuenta. Pulsa Entrar.",
      "auth/invalid-email": "el correo no es válido.",
      "auth/network-request-failed": "no hay internet. Revisa tu señal e intenta de nuevo.",
      "auth/too-many-requests": "muchos intentos. Espera unos minutos e intenta de nuevo.",
      "auth/operation-not-allowed": "ese método de acceso no está habilitado."
    };
    return codigos[e.code] || (e.message || "intenta de nuevo.");
  }

  /* ----- Lotes: lectura en tiempo real (misma colección de la app) ----- */
  function suscribirLotes() {
    // Sin orderBy para no exigir índice compuesto; se ordena en cliente.
    const q = query(collection(db, "lotes"), where("ownerUid", "==", uid));
    cancelarLotes = onSnapshot(q, (snap) => {
      const lotes = [];
      snap.forEach((d) => lotes.push({ id: d.id, ...d.data() }));
      lotes.sort((a, b) => (b.fechaCreacion || 0) - (a.fechaCreacion || 0));
      lotesCache = lotes;
      pintarLotes(lotes);
      suscribirSensores(lotes);
    }, (e) => {
      $("listaLotes").innerHTML = `<p class="seccion-sub" style="color:var(--rojo)">Error cargando lotes: ${esc(e.message)}</p>`;
    });
  }

  /* ----- Sensores: última lectura de cada lote, en tiempo real ----- */
  function suscribirSensores(lotes) {
    cancelarSensores.forEach((c) => c());
    cancelarSensores = [];
    if (!lotes.length) {
      $("listaSensores").innerHTML = `<p class="seccion-sub">Crea tu primer lote arriba para ver sus sensores aquí.</p>`;
      return;
    }
    const ultimas = new Map(); // loteId -> lectura
    const errores = new Map(); // loteId -> mensaje de error
    const pintar = () => pintarSensores(lotes, ultimas, errores);
    lotes.forEach((l) => {
      const q = query(
        collection(db, "lotes", l.id, "lecturas"),
        orderBy("ts", "desc"),
        limit(1)
      );
      cancelarSensores.push(onSnapshot(q, (snap) => {
        ultimas.delete(l.id);
        errores.delete(l.id);
        snap.forEach((d) => ultimas.set(l.id, { id: d.id, ...d.data() }));
        pintar();
      }, (err) => {
        errores.set(l.id, err.message);
        pintar();
      }));
    });
    pintar();
  }

  function haceCuanto(ts) {
    if (!ts) return "sin datos";
    const min = Math.floor((Date.now() - ts) / 60000);
    if (min < 1) return "ahora mismo";
    if (min < 60) return `hace ${min} min`;
    if (min < 1440) return `hace ${Math.floor(min / 60)} h`;
    return `hace ${Math.floor(min / 1440)} días`;
  }

  function alertasSensor(lec) {
    const a = [];
    if (lec.humSuelo != null && lec.humSuelo < 30)
      a.push(`⚠️ La tierra está seca (${Math.round(lec.humSuelo)}% de humedad). Conviene regar.`);
    if (lec.tempAmb != null && lec.tempAmb < 5)
      a.push(`🥶 Riesgo de helada: ${lec.tempAmb.toFixed(1)} °C. Proteja el cultivo.`);
    if (lec.bateria != null && lec.bateria < 20)
      a.push(`🔋 Batería baja del sensor (${Math.round(lec.bateria)}%).`);
    return a;
  }

  function pintarSensores(lotes, ultimas, errores) {
    const tarjetas = lotes.map((l) => {
      const errMsg = errores && errores.get(l.id);
      if (errMsg) {
        return `<div class="lote"><div class="info"><strong>${esc(l.nombre)}</strong><br>
          <small class="seccion-sub" style="color:var(--rojo)">\u26a0\ufe0f No se pudieron leer los sensores: ${esc(errMsg)}</small></div></div>`;
      }
      const lec = ultimas.get(l.id);
      if (!lec) {
        return `<div class="lote"><div class="info"><strong>${esc(l.nombre)}</strong><br>
          <small class="seccion-sub">Sin sensores todavía. Cuando los instales en este lote, aquí verás la temperatura y la humedad en tiempo real.</small></div></div>`;
      }
      const alertas = alertasSensor(lec).map((m) =>
        `<div class="alerta alerta-advertencia" style="margin:0.4rem 0">${esc(m)}</div>`).join("");
      const fmt = (v, dec, suf) => v != null ? `${Number(v).toFixed(dec)}${suf}` : "—";
      return `<div class="lote"><div class="info">
        <strong>${esc(l.nombre)}</strong> <small class="seccion-sub">· ${esc(haceCuanto(lec.ts))}</small><br>
        <span style="font-size:1.4rem">🌡️ ${fmt(lec.tempAmb, 1, " °C")}</span> &nbsp;
        <span style="font-size:1.4rem">💧 ${fmt(lec.humAmb, 0, " %")}</span> &nbsp;
        <span style="font-size:1.4rem">🌱 ${fmt(lec.humSuelo, 0, " %")}</span>
        ${lec.bateria != null ? `<br><small class="seccion-sub">🔋 Batería: ${Math.round(lec.bateria)}%${lec.dispositivoId ? ` · 📡 ${esc(lec.dispositivoId)}` : ""}</small>` : ""}
        ${alertas}
      </div></div>`;
    }).join("");
    $("listaSensores").innerHTML = tarjetas ||
      `<p class="seccion-sub">Sin lotes todavía.</p>`;
  }

  /* ----- Datos de prueba: lecturas de ejemplo en el primer lote ----- */
  $("btnDatosPrueba").onclick = async () => {
    if (!lotesCache.length) {
      $("msgDatosPrueba").innerHTML = `<div class="alerta alerta-advertencia">\u26a0\ufe0f Primero crea un lote arriba.</div>`;
      return;
    }
    const lote = lotesCache[0];
    const ahora = Date.now();
    const ejemplos = [];
    for (let i = 0; i < 8; i++) {
      const ts = ahora - i * 15 * 60000; // cada 15 min hacia atrás
      ejemplos.push({
        loteId: lote.id,
        ts,
        tempAmb: 22 + Math.sin(i / 2) * 4 + (Math.random() - 0.5),
        humAmb: 65 + Math.sin(i / 3) * 10 + (Math.random() - 0.5) * 4,
        humSuelo: 45 - i * 2 + (Math.random() - 0.5) * 3,
        bateria: 87 - i,
        dispositivoId: "nodo-01"
      });
    }
    try {
      for (const e of ejemplos) {
        await addDoc(collection(db, "lotes", lote.id, "lecturas"), e);
      }
      $("msgDatosPrueba").innerHTML = `<div class="alerta alerta-ok">\u2705 Listo: 8 lecturas de ejemplo en "${esc(lote.nombre)}". Ya las ves arriba 👆</div>`;
    } catch (err) {
      $("msgDatosPrueba").innerHTML = `<div class="alerta alerta-error">\u26a0\ufe0f No se pudo crear: ${esc(err.message)}</div>`;
    }
  };

  function pintarLotes(lotes) {
    $("contadorLotes").textContent = `(${lotes.length})`;
    if (!lotes.length) {
      $("listaLotes").innerHTML = `<p class="seccion-sub">Aún no tienes lotes. Crea el primero abajo 👇 (también puedes crearlo en la app).</p>`;
      return;
    }
    $("listaLotes").innerHTML = lotes.map((l) => {
      const gps = (l.latitud != null && l.longitud != null)
        ? `${Number(l.latitud).toFixed(4)}, ${Number(l.longitud).toFixed(4)}` : "";
      const ficha = [
        l.tipoSuelo ? `🌱 ${esc(etiquetaFicha(TIPOS_SUELO, l.tipoSuelo))}` : "",
        l.riego ? `💧 ${esc(etiquetaFicha(RIEGOS, l.riego))}` : "",
        l.pendiente ? `⛰️ ${esc(etiquetaFicha(PENDIENTES, l.pendiente))}` : ""
      ].filter(Boolean).join(" · ");
      const chips = [
        l.cultivo ? `🌾 ${esc(l.cultivo)}` : "",
        (l.hectareas != null && l.hectareas !== "") ? `📐 ${esc(String(l.hectareas))} ha` : ""
      ].filter(Boolean).map((c) => `<span class="chip">${c}</span>`).join("");
      return `<div class="lote">
        <div class="info">
          <strong>${esc(l.nombre)}</strong><br>${chips}
          ${gps ? `<small>📍 ${gps}</small>` : ""}
          ${l.notas ? `<small>📝 ${esc(l.notas)}</small>` : ""}
          ${ficha ? `<small>${ficha}</small>` : ""}
          ${l.historial ? `<small>📜 Antes aquí: ${esc(l.historial)}</small>` : ""}
        </div>
        <div class="acciones">
          <button class="btn btn-claro btn-pequeno" style="border:1px solid #cfd8d2" data-editar="${esc(l.id)}">✏️</button>
          <button class="btn btn-peligro btn-pequeno" data-borrar="${esc(l.id)}">🗑️</button>
        </div>
      </div>`;
    }).join("");

    $("listaLotes").querySelectorAll("[data-editar]").forEach((b) =>
      b.onclick = () => cargarEnFormulario(lotes.find((l) => l.id === b.dataset.editar)));
    $("listaLotes").querySelectorAll("[data-borrar]").forEach((b) =>
      b.onclick = async () => {
        if (confirm("¿Borrar este lote? También desaparecerá de la app.")) {
          await deleteDoc(doc(db, "lotes", b.dataset.borrar));
        }
      });
  }

  /* ----- Ficha del terreno: etiquetas bonitas para las claves guardadas ----- */
  const TIPOS_SUELO = { negra: "Tierra negra", arcillosa: "Barrosa", arenosa: "Arenosa", pedregosa: "Pedregosa", no_se: "Tierra (no sé)" };
  const RIEGOS = { lluvia: "Solo lluvia", goteo: "Goteo", aspersion: "Aspersión", gravedad: "Gravedad", pozo_rio: "Pozo o río", sin_agua: "Sin agua" };
  const PENDIENTES = { plano: "Plano", ladeado: "Ladeado", loma: "Loma" };
  const etiquetaFicha = (mapa, clave) => mapa[clave] || clave;

  /* ----- Lotes: crear / editar ----- */
  function leerFormulario() {
    const num = (id) => {
      const v = $(id).value.trim();
      return v === "" ? null : Number(v);
    };
    return {
      nombre: $("loteNombre").value.trim(),
      cultivo: $("loteCultivo").value.trim(),
      hectareas: Number($("loteHectareas").value),
      latitud: num("loteLat"),
      longitud: num("loteLng"),
      notas: $("loteNotas").value.trim(),
      // Ficha del terreno (opcional): solo viaja lo que el campesino llenó.
      tipoSuelo: $("loteTipoSuelo").value || null,
      riego: $("loteRiego").value || null,
      pendiente: $("lotePendiente").value || null,
      historial: $("loteHistorial").value.trim() || null
    };
  }

  $("formLote").onsubmit = async (e) => {
    e.preventDefault();
    const f = leerFormulario();
    if (!f.nombre || !f.cultivo || !(f.hectareas > 0)) {
      alert("Completa nombre, cultivo y hectáreas (mayor que 0).");
      return;
    }
    const datos = {
      ...f,
      fechaCreacion: Date.now(), // ms epoch, igual que LoteEntity en la app
      ownerUid: uid
    };
    const id = $("loteId").value;
    try {
      // En edición, la ficha vaciada se BORRA del documento (no queda el dato viejo).
      const FICHA = ["tipoSuelo", "riego", "pendiente", "historial"];
      if (id) {
        const actual = { ...datos, updatedAt: Date.now() };
        for (const k of FICHA) if (actual[k] == null) actual[k] = deleteField();
        await updateDoc(doc(db, "lotes", id), actual);
      } else {
        const limpio = Object.fromEntries(
          Object.entries(datos).filter(([, v]) => v !== null && v !== undefined)
        );
        await addDoc(collection(db, "lotes"), limpio);
      }
      limpiarFormulario();
    } catch (err) { alert("No se pudo guardar: " + err.message); }
  };

  /* ----- Botón "Usar mi ubicación": llena lat/lng con el GPS del navegador ----- */
  $("btnUbicacionLote").onclick = () => {
    const msg = $("msgUbicacion");
    if (!("geolocation" in navigator)) {
      msg.textContent = "Este navegador no tiene GPS.";
      return;
    }
    msg.textContent = "Buscando GPS…";
    const listo = (pos) => {
      $("loteLat").value = pos.coords.latitude.toFixed(6);
      $("loteLng").value = pos.coords.longitude.toFixed(6);
      msg.textContent = "Ubicación lista.";
    };
    const falloFinal = () => {
      msg.textContent = "No se pudo obtener la ubicación. Revisa el permiso de GPS y que la ubicación del teléfono esté encendida.";
    };
    // Segundo intento automático sin alta precisión (funciona bajo techo con wifi/red).
    const segundoIntento = () => {
      navigator.geolocation.getCurrentPosition(listo, falloFinal,
        { enableHighAccuracy: false, timeout: 30000, maximumAge: 600000 });
    };
    navigator.geolocation.getCurrentPosition(listo, segundoIntento,
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 60000 });
  };

  function cargarEnFormulario(l) {    $("loteId").value = l.id;
    $("loteNombre").value = l.nombre || "";
    $("loteCultivo").value = l.cultivo || "";
    $("loteHectareas").value = l.hectareas ?? "";
    $("loteLat").value = l.latitud ?? "";
    $("loteLng").value = l.longitud ?? "";
    $("loteNotas").value = l.notas || "";
    $("loteTipoSuelo").value = l.tipoSuelo || "";
    $("loteRiego").value = l.riego || "";
    $("lotePendiente").value = l.pendiente || "";
    $("loteHistorial").value = l.historial || "";
    // Si el lote ya tiene ficha, abrir la sección para que se vea.
    $("fichaTerreno").open = !!(l.tipoSuelo || l.riego || l.pendiente || l.historial);
    $("tituloFormLote").textContent = "✏️ Editar lote";
    $("btnGuardarLote").textContent = "Guardar cambios";
    $("btnCancelarLote").style.display = "inline-block";
    $("tituloFormLote").scrollIntoView({ behavior: "smooth" });
  }

  function limpiarFormulario() {
    $("formLote").reset();
    $("loteId").value = "";
    $("tituloFormLote").textContent = "➕ Nuevo lote";
    $("btnGuardarLote").textContent = "Guardar lote";
    $("btnCancelarLote").style.display = "none";
  }
  $("btnCancelarLote").onclick = limpiarFormulario;

  /* ----- Catálogo ICA: rejilla + ficha por producto ----- */
  function tipoEtiqueta(id) {
    const t = calcTipoProducto(id);
    if (t === "H") return { texto: "Herbicida", clase: "herbicida" };
    if (t === "FC" || t === "FS") return { texto: "Fungicida", clase: "fungicida" };
    if (t === "IS") return { texto: "Insecticida", clase: "insecticida" };
    return { texto: "Fitosanitario", clase: "otro" };
  }

  function paraQueSirve(p) {
    const t = calcTipoProducto(p.id);
    const accion = t === "H" ? "Controla malezas"
      : (t === "FC" || t === "FS") ? "Controla hongos y enfermedades de las plantas"
      : t === "IS" ? "Controla insectos que dañan el cultivo"
      : "Protege el cultivo";
    const cultivos = [...new Set(p.usos.map((u) => u.c))];
    const plagas = [...new Set(p.usos.map((u) => u.pl))];
    const cultTxt = cultivos.slice(0, 6).join(", ") + (cultivos.length > 6 ? ", entre otros" : "");
    const plagaTxt = plagas.slice(0, 3).join("; ") + (plagas.length > 3 ? "\u2026" : "");
    return accion + " en " + cultTxt + ". Combate: " + plagaTxt + ".";
  }

  function pintarCatalogo(filtro) {
    const f = (filtro || "").toLowerCase().trim();
    const lista = CATALOGO_CALC.filter((p) => {
      if (!f) return true;
      if ((p.n + " " + p.ia + " " + p.ica).toLowerCase().indexOf(f) >= 0) return true;
      return p.usos.some((u) => (u.c + " " + u.pl).toLowerCase().indexOf(f) >= 0);
    });
    if (!lista.length) {
      $("vistaProductos").innerHTML = `<p class="seccion-sub">No se encontró. Pruebe con el ingrediente activo, el cultivo o la plaga.</p>`;
      return;
    }
    $("vistaProductos").innerHTML = `<div class="prod-grid">` + lista.map((p) => {
      const te = tipoEtiqueta(p.id);
      return `<button class="prod-card" data-prod="${esc(p.id)}">
        <strong>${esc(p.n)}</strong>
        <span class="prod-ia">${esc(p.ia)}</span>
        <span class="prod-tipo ${te.clase}">${te.texto}</span>
        <span class="chip">ICA ${esc(p.ica)}</span><br>
        <span class="ver">Ver detalle \u2192</span>
      </button>`;
    }).join("") + `</div>`;
    $("vistaProductos").querySelectorAll("[data-prod]").forEach((b) => {
      b.onclick = () => verProducto(b.dataset.prod);
    });
  }

  function verProducto(id) {
    const p = CATALOGO_CALC.find((x) => x.id === id);
    if (!p) return;
    const te = tipoEtiqueta(p.id);
    const usosHtml = p.usos.map((u) => {
      let extra = "";
      if (u.agua != null) extra += `<small>💧 Agua: ${u.agua} L/ha</small>`;
      if (u.car != null) extra += `<small>\u23f3 No coseche antes de ${u.car} días</small>`;
      if (u.nt) extra += `<small>${esc(u.nt)}</small>`;
      return `<div class="uso-card">
        <strong>${esc(u.c)}</strong> \u2014 ${esc(u.pl)}<br>
        <span class="dosis">${u.dmin}\u2013${u.dmax} ${esc(u.u)}</span>
        ${extra}
      </div>`;
    }).join("");
    const filas = [
      ["Ingrediente activo", p.ia],
      ["Concentración", p.conc],
      ["Formulación", p.form],
      ["Categoría toxicológica", p.cat ? "Categoría " + p.cat : null],
      ["Titular del registro", p.tit]
    ];
    const tecnica = filas.filter((x) => x[1]).map((x) =>
      `<div><strong>${x[0]}:</strong> ${esc(x[1])}</div>`).join("");
    $("vistaProductos").innerHTML = `
      <button class="btn btn-claro btn-pequeno" id="prodVolver" style="border:1px solid #cfd8d2; margin-bottom:0.8rem">\u2190 Volver al catálogo</button>
      <div class="prod-ficha">
        <h3>${esc(p.n)}</h3>
        <span class="chip">ICA ${esc(p.ica)}</span>
        <span class="prod-tipo ${te.clase}">${te.texto}</span>
        <div class="prod-paraque"><strong>¿Para qué sirve?</strong><br>${esc(paraQueSirve(p))}</div>
        <h4 style="margin:0.6rem 0 0.4rem; color:var(--verde-oscuro)">Información técnica</h4>
        <div class="prod-tecnica">${tecnica}</div>
        <h4 style="margin:0.8rem 0 0.4rem; color:var(--verde-oscuro)">Usos registrados en la etiqueta (${p.usos.length})</h4>
        ${usosHtml}
      </div>`;
    $("prodVolver").onclick = () => pintarCatalogo($("prodBusqueda").value);
  }

  $("prodBusqueda").addEventListener("input", (e) => pintarCatalogo(e.target.value));

  /* ----- Calculadora de pesticidas ICA (3 pasos) ----- */
  let calcProducto = null;

  function calcFormatear(n) {
    return n.toLocaleString("es-CO", { maximumFractionDigits: 2 });
  }

  function calcPaso(n) {
    $("calcPaso1").style.display = n === 1 ? "block" : "none";
    $("calcPaso2").style.display = n === 2 ? "block" : "none";
    $("calcPaso3").style.display = n === 3 ? "block" : "none";
  }

  function calcPintarProductos(filtro) {
    const f = (filtro || "").toLowerCase().trim();
    const lista = [];
    for (const p of CATALOGO_CALC) {
      if (lista.length >= 30) break;
      if (!f) { lista.push(p); continue; }
      if (p.n.toLowerCase().indexOf(f) >= 0 || p.ia.toLowerCase().indexOf(f) >= 0) { lista.push(p); continue; }
      for (const u of p.usos) {
        if (u.c.toLowerCase().indexOf(f) >= 0 || u.pl.toLowerCase().indexOf(f) >= 0) { lista.push(p); break; }
      }
    }
    if (!lista.length) {
      $("calcListaProductos").innerHTML = `<p class="seccion-sub">No se encontró ese producto. Pruebe con el ingrediente activo o el cultivo.</p>`;
      return;
    }
    $("calcListaProductos").innerHTML = lista.map((p) =>
      `<button class="btn btn-claro btn-pequeno" data-n="${esc(p.n)}" style="border:1px solid #cfd8d2">${esc(p.n)} <small>ICA ${esc(p.ica)}</small></button>`
    ).join("");
    const porNombre = {};
    for (const p of CATALOGO_CALC) porNombre[p.n] = p;
    $("calcListaProductos").querySelectorAll("button").forEach((b) => {
      b.onclick = () => calcElegirProducto(porNombre[b.dataset.n]);
    });
  }

  function calcElegirProducto(p) {
    calcProducto = p;
    $("calcProductoNombre").textContent = p.n + " (ICA " + p.ica + ")";
    $("calcUso").innerHTML = p.usos.map((u, i) =>
      `<option value="${i}">${esc(u.c)} \u2014 ${esc(u.pl)} (${u.dmin}\u2013${u.dmax} ${esc(u.u)})</option>`
    ).join("");
    $("calcArea").value = "";
    $("calcDosisPlaneada").value = "";
    calcPaso(2);
  }

  function calcHacer() {
    if (!calcProducto) return;
    const uso = calcProducto.usos[Number($("calcUso").value) || 0];
    const area = parseFloat(String($("calcArea").value).replace(",", ".")) || 0;
    if (!(area > 0)) {
      $("calcResultado").innerHTML = `<p class="seccion-sub" style="color:var(--rojo)">Escriba cuántas hectáreas va a fumigar.</p>`;
      calcPaso(3);
      return;
    }
    const pMin = uso.dmin * area;
    const pMax = uso.dmax * area;
    let html = `<div class="res-card">
      <div class="res-nombre">${esc(calcProducto.n)}<span class="res-ica">ICA ${esc(calcProducto.ica)}</span></div>
      <div class="res-uso">${esc(uso.c)} \u2014 ${esc(uso.pl)} \u00b7 ${calcFormatear(area)} ha</div>
      <div class="res-num">${calcFormatear(pMin)} a ${calcFormatear(pMax)} <small>${esc(uso.u)}</small></div>` +
      (uso.agua != null ? `<div class="res-sec">💧 <strong>${calcFormatear(uso.agua * area)} litros</strong> de agua</div>` : "") +
      (uso.car != null ? `<div class="res-sec">\u23f3 No coseche antes de <strong>${uso.car} días</strong></div>` : "") +
      `</div>`;
    const dosisTxt = String($("calcDosisPlaneada").value).replace(",", ".").trim();
    const d = parseFloat(dosisTxt);
    if (dosisTxt !== "" && !isNaN(d) && d > 0) {
      if (d < uso.dmin) {
        html += `<div class="alerta alerta-advertencia">\u26a0\ufe0f La dosis de ${calcFormatear(d)} ${esc(uso.u)} está POR DEBAJO del rango de la etiqueta (${uso.dmin}\u2013${uso.dmax} ${esc(uso.u)}). Una dosis baja puede no controlar la plaga y generar resistencia.</div>`;
      } else if (d > uso.dmax) {
        html += `<div class="alerta alerta-error">🛑 La dosis de ${calcFormatear(d)} ${esc(uso.u)} está POR ENCIMA del rango de la etiqueta (${uso.dmin}\u2013${uso.dmax} ${esc(uso.u)}). NO aplique de más: es ilegal, daña el cultivo, el ambiente y su salud.</div>`;
      } else {
        html += `<div class="alerta alerta-ok">\u2705 La dosis de ${calcFormatear(d)} ${esc(uso.u)} está DENTRO del rango de la etiqueta (${uso.dmin}\u2013${uso.dmax} ${esc(uso.u)}).</div>`;
      }
    }
    if (uso.nt) html += `<p class="seccion-sub"><small>${esc(uso.nt)}</small></p>`;
    html += calcHtmlGota();
    $("calcResultado").innerHTML = html;
    calcPaso(3);
  }

  $("calcBusqueda").addEventListener("input", (e) => calcPintarProductos(e.target.value));
  $("calcCalcular").onclick = calcHacer;
  $("calcCambiarProducto").onclick = () => { calcPaso(1); };
  $("calcNuevo").onclick = () => { calcPaso(1); $("calcBusqueda").value = ""; calcPintarProductos(""); };
  /* ----- Gota recomendada por dron (guia ASABE S572.3) ----- */
  function calcTipoProducto(id) {
    switch (id) {
      case "dual-gold-960-ec":
      case "clincher-ec":
      case "facet-sc":
      case "propanil-480-adama":
      case "gesaprim-nueve-90-wdg":
      case "roundup-activo":
      case "sofit":
        return "H";
      case "daconil-720-sc":
      case "curzate-60":
      case "manzate-200-wg":
      case "dithane-f-mb":
        return "FC";
      case "engeo":
      case "cormoran-ec":
        return "IS";
      case "alto-100-sl":
      case "amistar-top":
      case "ridomil-gold-mz-68-wp":
      case "tilt-250-ec":
      case "amistar-50-wg":
      case "opera-sc":
      case "silvacur-combi-ec-300":
      case "nativo-sc-300":
        return "FS";
      default:
        return "OTRO";
    }
  }

  function calcClaseAsabe(micras) {
    if (micras < 60) return "Extremadamente fina";
    if (micras <= 105) return "Muy fina";
    if (micras <= 235) return "Fina";
    if (micras <= 340) return "Media";
    if (micras <= 403) return "Gruesa";
    if (micras <= 502) return "Muy gruesa";
    if (micras <= 665) return "Extremadamente gruesa";
    return "Ultra gruesa";
  }

  function calcRangoGota(tipo) {
    if (tipo === "H") return [236, 403];
    if (tipo === "FC") return [106, 340];
    if (tipo === "IS" || tipo === "FS") return [236, 340];
    return [106, 403];
  }

  function calcConsejoSimple(tipo) {
    if (tipo === "H") return "Use gota gruesa: cae rápido al suelo y el viento se la lleva menos.";
    if (tipo === "FC") return "Use gota fina: cubre mejor la hoja por todos lados.";
    if (tipo === "IS" || tipo === "FS") return "Use gota media: buen equilibrio entre cubrir bien y que no se la lleve el viento.";
    return "Use gota media y revise lo que dice la etiqueta del producto.";
  }

  function calcPintarDrones() {
    $("calcDron").innerHTML = AERONAVES_CALC.map((a) => {
      const det = (a.mmin != null && a.mmax != null) ? (a.mmin + "\u2013" + a.mmax + " micras") : "datos no verificados";
      const sel = a.id === "dji-t55" ? " selected" : "";
      return `<option value="${esc(a.id)}"${sel}>${esc(a.n)} (${det})</option>`;
    }).join("");
  }

  function calcHtmlGota() {
    const aero = AERONAVES_CALC.find((a) => a.id === $("calcDron").value) || AERONAVES_CALC[0];
    const tipo = calcTipoProducto(calcProducto.id);
    const rg = calcRangoGota(tipo);
    const rMin = rg[0], rMax = rg[1];
    const clase = calcClaseAsabe(Math.round((rMin + rMax) / 2));
    const consejo = calcConsejoSimple(tipo);
    let alcanza = false, adv = null;
    if (!aero.v || aero.mmin == null || aero.mmax == null) {
      adv = "Los datos de gota de " + aero.n + " no están verificados con ficha oficial del fabricante. " +
        "No se puede confirmar el ajuste: verifique el manual de su equipo o consulte un ingeniero agrónomo.";
    } else if (aero.mmax < rMin || aero.mmin > rMax) {
      adv = aero.n + " genera gotas de " + aero.mmin + "\u2013" + aero.mmax + " micras y no alcanza el rango recomendado " +
        "para este producto (" + rMin + "\u2013" + rMax + " micras). Ajuste la configuración del equipo o consulte un ingeniero agrónomo antes de aplicar.";
    } else {
      alcanza = true;
    }
    const equipo = alcanza
      ? ("Su " + aero.n + " sí puede dar ese tamaño de gota.")
      : ("Revise su equipo: no se pudo confirmar que su " + aero.n + " dé ese tamaño de gota.");
    let html = `<h3 style="margin-top:1.2rem">🚁 Gota recomendada</h3>` +
      `<div class="producto"><strong>${esc(consejo)}</strong><br><small>${esc(equipo)}</small><br>` +
      `<small>Detalle técnico: ${rMin}\u2013${rMax} micras \u00b7 clase ${esc(clase)} (ASABE S572.3)</small></div>`;
    if (adv) html += `<div class="alerta alerta-advertencia">\u26a0\ufe0f ${esc(adv)}</div>`;
    html += `<p class="seccion-sub"><small>Guía agronómica general. La etiqueta física del producto manda; ante cualquier duda consulte un ingeniero agrónomo.<br>💨 Mida el viento a la altura del cultivo antes de aplicar. Sobre ~15 km/h NO aplique.</small></p>`;
    return html;
  }

  calcPintarProductos("");
  calcPintarDrones();
}

